select json_object('a', id) as a, json_object('b', id) as b, json_object('c', id) as c, (select json_object('d', p.id) from posts p limit 1) as d, (select json_object('e', p.id) from posts p limit 1) as e, (select json_object('f', p.id) from posts p limit 1) as f, (select json_object('g', p.id) from posts p limit 1) as g, (select json_object('h', p.id) from posts p limit 1) as h, (select json_object('i', p.id) from posts p limit 1) as i, (select json_object('j', p.id) from posts p limit 1) as j, (select json_object('k', p.id) from posts p limit 1) as k from users
